38	  // This method is called regularly by the controller
39	  
40	  // If sound is enabled, simulate clicks based on radiation level
41	  if (_sound_enabled) {
42	    uint32_t current_time = millis();
43	    
44	    // We'll use a probabilistic approach to simulate clicks based on CPS
45	    // This will make clicks more random like actual Geiger counter clicks
46	    
47	    // The higher the CPS, the more likely we are to play a click in any given interval
48	    // For example, if CPS is 10, we should play approximately 10 clicks per second
49	    
50	    // Calculate probability of a click in this interval
51	    // We check every ~10ms, so for a CPS of 10, probability should be 10/100 = 0.1
52	    float click_probability = _last_cps / 100.0f;
53	    
54	    // Generate a random number between 0 and 1
55	    float random_value = (float)random(100) / 100.0f;
56	    
57	    // If random value is less than probability and enough time has passed, play a click
58	    if (random_value < click_probability && current_time - _last_click_time >= MIN_CLICK_INTERVAL) {
59	      // Play a click sound at user volume
60	      Preferences p; uint8_t volPct = D_AUDIO_VOLUME; if (p.begin("data", true)) { volPct = p.getUChar("audio_volume", D_AUDIO_VOLUME); p.end(); }
61	      uint16_t vol = (uint16_t)volPct * 255 / 100; if (vol > 255) vol = 255;
62	      M5.Speaker.setVolume((uint8_t)vol);
63	      
64	      // Vary frequency based on CPS - higher CPS = higher frequency
65	      uint16_t frequency = BASE_FREQUENCY + (_last_cps * 10);
66	      if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;
67	      
68	      M5.Speaker.tone(frequency, CLICK_DURATION, _click_channel, true);
69	      
70	      // Update last click time
71	      _last_click_time = current_time;
72	      
73	      // Rotate through channels to allow overlapping clicks
74	      _click_channel = (_click_channel + 1) % 8;
75	    }
76	    
77	    // Every second, update the CPS value from the global data
78	    static uint32_t last_cps_update = 0;
79	    if (current_time - last_cps_update >= 1000) {
80	      // Get CPS from global data (this is a hack, but should work)
81	      extern uint32_t g_cps;  // Changed to uint32_t for high count rates
82	      _last_cps = g_cps;
83	      last_cps_update = current_time;
84	    }
85	  }
86	  
87	  // Update our data (sound enabled status)
88	  data = _sound_enabled;
89	  return e_worker_data_read;
90	}
