40	void ConfigModeScreen::render_audio_volume_page(const worker_map_t& workers, const handler_map_t& handlers) {
41	  auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
42	  uint8_t current = settings->get_audio_volume();
43	
44	  // Draw button indicators at bottom of screen
45	  drawButton1("-5%\nHold:-20%");
46	  drawButton2("+5%\nHold:+20%");
47	  drawButton3("Back");
48	
49	  M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
50	  M5.Lcd.setCursor(0, 50, &fonts::Font2);
51	  M5.Lcd.printf("Audio Volume\n\n");
52	  M5.Lcd.printf("Current: %u%%\n\n", current);
53	  M5.Lcd.printf("Controls the global audio volume for\n");
54	  M5.Lcd.printf("clicks and CPM alert sounds.\n\n");
55	  M5.Lcd.setTextColor(LCD_COLOR_STALE_INCOMPLETE, LCD_COLOR_BACKGROUND);
56	  M5.Lcd.printf("Range: 0-100%%\n");
57	}
58	
59	void ConfigModeScreen::render_dim_brightness_page(const worker_map_t& workers, const handler_map_t& handlers) {
60	  auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
61	  uint8_t current = settings->get_dim_brightness();
62	
63	  // Draw button indicators at bottom of screen
64	  drawButton1("-5%\nHold:-20%");
65	  drawButton2("+5%\nHold:+20%");
66	  drawButton3("Back");
67	
68	  M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
69	  M5.Lcd.setCursor(0, 50, &fonts::Font2);
70	  M5.Lcd.printf("Dim Brightness\n\n");
71	  M5.Lcd.printf("Current: %u%%\n\n", current);
72	  M5.Lcd.printf("Controls the screen brightness used\n");
73	  M5.Lcd.printf("when the device is DIM or the\n");
74	  M5.Lcd.printf("animated screensaver is active.\n\n");
75	  M5.Lcd.setTextColor(LCD_COLOR_STALE_INCOMPLETE, LCD_COLOR_BACKGROUND);
76	  M5.Lcd.printf("Range: 0-100%%\n");
77	}
78	
79	BaseScreen* ConfigModeScreen::handle_input(Controller& controller, const worker_map_t& workers) {
80	  if (menu_open()) {
81	    auto* new_screen = handle_menu_input(controller, workers, CONFIG_MODE_MENU, e_config_MENU_MAX);
82	    if (new_screen) {
83	      return new_screen;
84	    }
85	    // Handle menu selection
86	    if (_current_page == e_config_page_reset_dose) {
87	      auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
88	      settings->reset_dose_rate();
89	      
90	      // Clear screen and show restart message
91	      M5.Lcd.clear(LCD_COLOR_BACKGROUND);
92	      M5.Lcd.setRotation(3);
93	      M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
94	      M5.Lcd.setCursor(46, 78, &fonts::Font4);  // Centered horizontally (320 - text width) / 2
95	      M5.Lcd.printf("DOSE RATE RESET\n");
96	      M5.Lcd.setCursor(100, 120, &fonts::Font2);
97	      M5.Lcd.printf("Restarting device...\n");
98	      
99	      delay(2000); // Wait 2 seconds
100	      DeviceUtils::shutdown(true); // Restart the device
101	    }
102	    else if (_current_page == e_config_page_back_to_main) {
103	      return &MenuWindow_i;
104	    }
105	  }
106	  else {
107	    auto button1 = workers.worker<ZenButton>(k_worker_button_1);
108	    auto button2 = workers.worker<ZenButton>(k_worker_button_2);
109	    auto button3 = workers.worker<ZenButton>(k_worker_button_3);
110	    if (button1->is_fresh() && button1->get_data().shortPress) {
111	      // Check if we're on the CPM threshold page for decrement functionality
112	      if (_current_page == e_config_page_cpm_threshold) {
113	        auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
114	        uint16_t current_threshold = settings->get_alert_threshold();
115	        uint16_t decrement = button1->get_data().longPress ? 100 : 10;
116	        uint16_t new_threshold;
117	        
118	        // Handle underflow protection
119	        if (current_threshold <= decrement || current_threshold - decrement < 10) {
120	          new_threshold = 10;  // Minimum threshold
121	        } else {
122	          new_threshold = current_threshold - decrement;
123	        }
124	        
125	        if (new_threshold != current_threshold) {
126	          settings->set_alert_threshold(new_threshold, false);
127	          
128	          // Save to SD card
129	          if (SDInterface::i().ready()) {
130	            SDInterface::i().write_safezen_file_from_settings(*settings, false);
131	          }
132	          
133	          force_next_render();
134	          M5_LOGD("CPM threshold decreased to: %u", new_threshold);
135	        }
136	      }
137	      // Check if we're on the click sound page for toggle functionality
138	      else if (_current_page == e_config_page_click_sound) {
139	        auto sound_manager = workers.worker<SoundManager>(k_worker_sound_manager);
140	        if (sound_manager) {
141	          bool new_state = sound_manager->toggleSound();
142	          // Persist confirmation already handled by SoundManager; also mirror to SD settings file
143	          auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
144	          if (SDInterface::i().ready()) {
145	            SDInterface::i().write_safezen_file_from_settings(*settings, false);
146	          }
147	          force_next_render();
148	          M5_LOGD("Click sound toggled to: %s", new_state ? "ENABLED" : "DISABLED");
149	        }
150	      }
151	      // Check if we're on the error alert sound page for toggle functionality
152	      else if (_current_page == e_config_page_error_alert_sound) {
153	        auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
154	        bool current_setting = settings->get_error_alert_sound();
155	        bool new_setting = !current_setting;
156	        
157	        settings->set_error_alert_sound(new_setting, false);
158	        
159	        // Save to SD card
160	        if (SDInterface::i().ready()) {
161	          SDInterface::i().write_safezen_file_from_settings(*settings, false);
162	        }
163	        
164	        force_next_render();
165	        M5_LOGD("Error alert sound toggled to: %s", new_setting ? "ENABLED" : "DISABLED");
166	      }
167	      // Check if we're on the dim brightness page for decrement functionality
168	      else if (_current_page == e_config_page_dim_brightness) {
169	        auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
170	        uint8_t current = settings->get_dim_brightness();
171	        uint8_t step = button1->get_data().longPress ? 20 : 5;
172	        uint8_t new_value = (current > step) ? (uint8_t)(current - step) : 0;
173	
174	        if (new_value != current) {
175	          settings->set_dim_brightness(new_value, false);
176	          if (SDInterface::i().ready()) {
177	            SDInterface::i().write_safezen_file_from_settings(*settings, false);
178	          }
179	          force_next_render();
180	          M5_LOGD("Dim brightness decreased to: %u%%", new_value);
181	        }
182	      }
183	      else if (_current_page == e_config_page_audio_volume) {
184	        auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
185	        uint8_t current = settings->get_audio_volume();
186	        uint8_t step = button1->get_data().longPress ? 20 : 5;
187	        uint8_t new_value = (current > step) ? (uint8_t)(current - step) : 0;
188	
189	        if (new_value != current) {
190	          settings->set_audio_volume(new_value, false);
191	          if (SDInterface::i().ready()) {
192	            SDInterface::i().write_safezen_file_from_settings(*settings, false);
193	          }
194	          force_next_render();
195	          M5_LOGD("Audio volume decreased to: %u%%", new_value);
196	        }
197	      }
198	      else {
199	        open_menu(true);
200	        M5.Lcd.clear(LCD_COLOR_BACKGROUND);  // Clear screen when opening menu
201	        force_next_render();
202	      }
203	    }
204	    if (button2->is_fresh() && button2->get_data().shortPress) {
205	      // screen specific action
206	      switch (_current_page) {
207	        case e_config_page_reset_all:
208	          M5.Lcd.clear(LCD_COLOR_BACKGROUND);
209	          M5.Lcd.setRotation(3);
210	          M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
211	          M5.Lcd.setCursor(30, 78, &fonts::Font4);
212	          M5.Lcd.printf("RESET IN PROGRESS\n");
213	          M5.Lcd.setCursor(5, 120, &fonts::Font2);
214	
215	          M5.Lcd.printf("Removing all log files, This can take a while...\n");
216	          controller.factory_reset();
217	          M5.Lcd.clear(LCD_COLOR_BACKGROUND);
218	          M5.Lcd.setRotation(3);
219	          M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
220	          M5.Lcd.setCursor(27, 78, &fonts::Font4);
221	          M5.Lcd.printf("DEVICE MEMORY AND\n");
222	          M5.Lcd.setCursor(27, 110, &fonts::Font4);
223	          M5.Lcd.printf("SD HAVE BEEN RESET\n");
224	          M5.Lcd.setCursor(70, 160, &fonts::Font2);
225	          M5.Lcd.printf("Please turn off the device...\n");
226	          delay(UINT32_MAX); // Sleep for a long time.
227	          break;
228	        case e_config_page_main:
229	          _main_page_info_section = (_main_page_info_section + 1) % e_config_section_MAX;
230	          force_next_render();
231	          break;
232	        case e_config_page_set_home_gps: {
233	          // Set current GPS location as home
234	          auto* gps = workers.worker<GpsConnector>(k_worker_gps_connector);
235	          auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
236	          
237	          if (gps && gps->active() && gps->get_data().location_valid) {
238	            double new_lat = gps->get_data().latitude;
239	            double new_lon = gps->get_data().longitude;
240	            
241	            // Save the new home location
242	            settings->set_fixed_latitude(new_lat, false);
243	            settings->set_fixed_longitude(new_lon, false);
244	            
245	            // Also update last known location for reference
246	            settings->set_last_latitude(new_lat, false);
247	            settings->set_last_longitude(new_lon, false);
248	            
249	            // Save to SD card
250	            if (SDInterface::i().ready()) {
251	              SDInterface::i().write_safezen_file_from_settings(*settings, false);
252	            }
253	            
254	            set_status_message(F(" HOME GPS LOCATION SET! "));
255	            force_next_render();
256	            M5_LOGD("Home GPS location set to: Lat %.6f, Lon %.6f", new_lat, new_lon);
257	          } else {
258	            set_status_message(F(" NO VALID GPS FIX! "));
259	            M5_LOGD("Cannot set home GPS - no valid fix");
260	          }
261	          break;
262	        }
263	        case e_config_page_cpm_threshold: {
264	          auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
265	          uint16_t current_threshold = settings->get_alert_threshold();
266	          uint16_t increment = button2->get_data().longPress ? 100 : 10;
267	          uint16_t new_threshold = current_threshold + increment;
268	          
269	          // Clamp to reasonable range
270	          if (new_threshold > 9999) {
271	            new_threshold = 9999;
272	          }
273	          if (new_threshold < 10) {
274	            new_threshold = 10;
275	          }
276	          
277	          if (new_threshold != current_threshold) {
278	            settings->set_alert_threshold(new_threshold, false);
279	            
280	            // Save to SD card
281	            if (SDInterface::i().ready()) {
282	              SDInterface::i().write_safezen_file_from_settings(*settings, false);
283	            }
284	            
285	            force_next_render();
286	            M5_LOGD("CPM threshold updated to: %u", new_threshold);
287	          }
288	          break;
289	        }
290	        case e_config_page_dim_brightness: {
291	          auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
292	          uint8_t current = settings->get_dim_brightness();
293	          uint8_t step = button2->get_data().longPress ? 20 : 5;
294	          uint16_t temp = current + step; // use wider type to avoid overflow before clamp
295	          uint8_t new_value = (temp > 100) ? 100 : (uint8_t)temp;
296	
297	          if (new_value != current) {
298	            settings->set_dim_brightness(new_value, false);
299	            if (SDInterface::i().ready()) {
300	              SDInterface::i().write_safezen_file_from_settings(*settings, false);
301	            }
302	            force_next_render();
303	            M5_LOGD("Dim brightness increased to: %u%%", new_value);
304	          }
305	          break;
306	        }
307	        case e_config_page_audio_volume: {
308	          auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
309	          uint8_t current = settings->get_audio_volume();
310	          uint8_t step = button2->get_data().longPress ? 20 : 5;
311	          uint16_t temp = current + step; // use wider type to avoid overflow before clamp
312	          uint8_t new_value = (temp > 100) ? 100 : (uint8_t)temp;
313	
314	          if (new_value != current) {
315	            settings->set_audio_volume(new_value, false);
316	            if (SDInterface::i().ready()) {
317	              SDInterface::i().write_safezen_file_from_settings(*settings, false);
318	            }
319	            force_next_render();
320	            M5_LOGD("Audio volume increased to: %u%%", new_value);
321	          }
322	          break;
323	        }
324	        default:
325	          break;
326	      }
327	    }
328	    if (button3->is_fresh() && button3->get_data().shortPress) {
329	      // Handle page-specific back navigation
330	      switch (_current_page) {
331	        case e_config_page_cpm_threshold:
332	        case e_config_page_click_sound:
333	        case e_config_page_error_alert_sound:
334	        case e_config_page_dim_brightness:
335	        case e_config_page_audio_volume:
336	        case e_config_page_set_home_gps:
337	          // Go back to config menu, not main menu
338	          _current_page = e_config_page_main;
339	          M5.Lcd.clear(LCD_COLOR_BACKGROUND);  // Clear screen to avoid visual artifacts
340	          open_menu(false);
341	          force_next_render();
342	          return nullptr;  // Stay on config screen
343	        default:
344	          // For other pages, go back to main menu
345	          return &MenuWindow_i;
346	      }
347	    }
348	  }
349	
350	  return nullptr;
351	}
