353	void ConfigModeScreen::render(const worker_map_t& workers, const handler_map_t& handlers, bool force) {
354	  if (menu_open()) {
355	    if (!force) {
356	      return;
357	    }
358	    render_menu(CONFIG_MODE_MENU, e_config_MENU_MAX, true, 1);
359	  }
360	  else {
361	    if (!force) {
362	      return;
363	    }
364	    clear_screen_content();
365	
366	    switch (_current_page) {
367	      case e_config_page_main:
368	        render_page_main(workers, handlers);
369	        break;
370	      case e_config_page_ap:
371	        render_page_ap(workers, handlers);
372	        break;
373	      case e_config_page_wifi:
374	        render_page_wifi(workers, handlers);
375	        break;
376	      case e_config_page_sd_wipe:
377	        render_sd_wipe(workers, handlers);
378	        break;
379	      case e_config_page_cpm_threshold:
380	        render_cpm_threshold_page(workers, handlers);
381	        break;
382	      case e_config_page_click_sound:
383	        render_click_sound_page(workers, handlers);
384	        break;
385	      case e_config_page_error_alert_sound:
386	        render_error_alert_sound_page(workers, handlers);
387	        break;
388	      case e_config_page_dim_brightness:
389	        render_dim_brightness_page(workers, handlers);
390	        break;
391	      case e_config_page_audio_volume:
392	        render_audio_volume_page(workers, handlers);
393	        break;
394	      case e_config_page_set_home_gps:
395	        render_set_home_gps_page(workers, handlers);
396	        break;
397	      case e_config_page_reset_all:
398	        render_reset_device_sd(workers, handlers);
399	        break;
400	      default:
401	        break;
402	    }
403	  }
404	}
