598	  M5.Lcd.setCursor(0, 50, &fonts::Font2);
599	  M5.Lcd.printf("Set Home GPS Location\n\n");
600	  
601	  // Show current home location
602	  M5.Lcd.printf("Current Home (Real Time):\n");
603	  M5.Lcd.setTextColor(LCD_COLOR_STALE_INCOMPLETE, LCD_COLOR_BACKGROUND);
604	  M5.Lcd.printf("Lat: %.6f\n", settings->get_fixed_latitude());
605	  M5.Lcd.printf("Lon: %.6f\n", settings->get_fixed_longitude());
606	  
607	  // Show current GPS location if available
608	  M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
609	  M5.Lcd.printf("Current GPS Position:\n");
610	  
611	  if (gps && gps->active() && gps->get_data().location_valid) {
612	    M5.Lcd.setTextColor(LCD_COLOR_ACTIVITY, LCD_COLOR_BACKGROUND);
613	    M5.Lcd.printf("Lat: %.6f\n", gps->get_data().latitude);
614	    M5.Lcd.printf("Lon: %.6f\n", gps->get_data().longitude);
615	  } else if (gps && gps->active()) {
616	    M5.Lcd.setTextColor(LCD_COLOR_STALE_INCOMPLETE, LCD_COLOR_BACKGROUND);
617	    M5.Lcd.printf("Waiting for GPS fix...\n");
618	    M5.Lcd.printf("Sats in view: %d\n", gps ? gps->get_data().satsInView : 0);
619	  } else {
620	    M5.Lcd.setTextColor(LCD_COLOR_ERROR, LCD_COLOR_BACKGROUND);
621	    M5.Lcd.printf("GPS not available\n");
622	  }
623	  
624	  M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
625	  M5.Lcd.printf("\nPress B to set current GPS\n");
626	  M5.Lcd.printf("position as home location.\n");
627	}
