629	void ConfigModeScreen::enter_screen(Controller& controller) {
630	  // Ensure low power mode is disabled so that WiFi/AP will start reliably
631	  PowerManager::exitLowPowerMode();
632	
633	  // If entering the Settings screen from outside and we're on the main page,
634	  // force the menu to open at the main entry
635	  if (_current_page == e_config_page_main) {
636	    _menu_index = e_config_page_main;
637	    open_menu(true);
638	    return;
639	  }
640	
641	  // For other pages, perform page-specific actions when the page is entered
642	  switch (_current_page) {
643	    case e_config_page_ap:
644	      WiFiWrapper_i.start_ap_server(controller.get_settings().get_device_id(), controller.get_settings().get_ap_password());
645	      controller.set_worker_active(k_worker_config_server, true);
646	      break;
647	    case e_config_page_wifi:
648	      WiFiWrapper_i.connect_wifi(controller.get_settings().get_wifi_ssid(), controller.get_settings().get_wifi_password());
649	      controller.set_worker_active(k_worker_config_server, true);
650	      break;
651	    case e_config_page_load_sd_config:
652	      if (controller.load_sd_config()) {
653	        set_status_message(F(" SD CONFIG LOADED, settings have been updated! "));
654	      }
655	      else {
656	        set_status_message(F(" LOAD CONFIG FAILED, no config or SD-card! "));
657	      }
658	      _current_page = e_config_page_main; // Back on main page
659	      open_menu(true);       // Re-enter menu
660	      break;
661	    case e_config_page_save_config_to_sd:
662	      if (controller.write_sd_config()) {
663	        set_status_message(F(" CONFIG SAVED, settings have been saved to SD! "));
664	      }
665	      else {
666	        set_status_message(F(" WRITE CONFIG FAILED, no SD-card! "));
667	      }
668	      _current_page = e_config_page_main; // Back on main page
669	      open_menu(true);       // Re-enter menu
670	      break;
671	    default:
672	      break;
673	  }
674	}
675	
676	void ConfigModeScreen::leave_screen(Controller& controller) {
677	  switch (_current_page) {
678	    case e_config_page_ap:
679	      WiFiWrapper_i.stop_ap_server();
680	      controller.set_worker_active(k_worker_config_server, false);
681	      break;
682	    case e_config_page_wifi:
683	      WiFiWrapper_i.disconnect_wifi();
684	      controller.set_worker_active(k_worker_config_server, false);
685	      break;
686	    default:
687	      break;
688	  }
689	
690	  // Set page to main in case we left through main menu
691	  _current_page = e_config_page_main;
692	  _main_page_info_section = e_config_section_device;
693	}
