334	      } else {
335	        M5_LOGD("Unable to load access_point_password");
336	      }
337	    }
338	    // Check wifi_ssid2 and wifi_password2 BEFORE wifi_ssid and wifi_password
339	    // because "wifi_ssid2" starts with "wifi_ssid" and would match incorrectly
340	    else if (line.startsWith(SD_CONFIG_FIELD_WIFI_SSID2)) {
341	      if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_WIFI_SSID2) < CONFIG_VAL_MAX && sscanf(line.c_str(), sd_config_wifi_ssid2_f, wifi_ssid2)) {
